39:   function pointSegDist(px, py, x1, y1, x2, y2) {
40:     const dx = x2 - x1;
41:     const dy = y2 - y1;
42:     const l2 = dx * dx + dy * dy;
43:     if (l2 < 0.0001) return Math.hypot(px - x1, py - y1);
44:     let t = ((px - x1) * dx + (py - y1) * dy) / l2;
45:     t = clamp(t, 0, 1);
46:     return Math.hypot(px - (x1 + dx * t), py - (y1 + dy * t));
47:   }
