515:       id: def.id,
516:       name: def.name,
517:       x: def.x,
518:       y: def.y,
519:       radius: WALL_RADIUS,
520:       base: def.base,
521:       perk: def.perk,
522:       mod: def.mod,
523:       state: {
524:         owned: false,
525:         integrity: 0,
526:         maxIntegrity: def.base,
527:         armor: 0,
528:         traps: 0,
529:         haunt: 0,
