845:   function spawnWildCompanions(count) {
846:     const roles = Object.keys(ROLES);
847:     const usedNames = new Set(game.companions.map((c) => c.name));
848:     const openNames = NAMES.filter((n) => !usedNames.has(n));
849:     for (let i = 0; i < count; i++) {
850:       let x = 0;
851:       let y = 0;
852:       let ok = false;
853:       for (let tries = 0; tries < 120 && !ok; tries++) {
854:         x = 160 + Math.random() * (WORLD.w - 320);
855:         y = 160 + Math.random() * (WORLD.h - 320);
856:         ok = true;
857:         for (const s of shelters) if (dist(x, y, s.x, s.y) < s.radius + 140) ok = false;
858:         for (const c of game.companions) if (c.state === 'wild' && dist(x, y, c.x, c.y) < 220) ok = false;
859:       }
860:       if (!ok) continue;
861:       const role = pick(roles);
862:       const name = openNames.length ? openNames.splice(randInt(0, openNames.length - 1), 1)[0] : pick(NAMES);
863:       const def = ROLES[role];
864:       game.companions.push({
865:         id: 'c' + Math.random().toString(36).slice(2, 9),
866:         name,
867:         role,
868:         state: 'wild',
869:         x, y,
870:         hp: def.hp,
871:         maxHp: def.hp,
872:         angle: Math.random() * TAU,
873:         fireTimer: Math.random(),
874:         seed: Math.random() * 10,
875:         shelterId: null,
876:         targetShelterId: null,
877:         hitFlash: 0
878:       });
879:     }
880:   }
