930:   function sendCompanionToShelter(c) {
931:     if (c.state !== 'team') return;
932:     const occupied = new Set(residents().map((r) => r.shelterId));
933:     let candidates = shelters.filter((s) => !s.state.collapsed && !occupied.has(s.id) && s.id !== game.activeShelter);
934:     if (!candidates.length) candidates = shelters.filter((s) => !s.state.collapsed && !occupied.has(s.id));
935:     if (!candidates.length) candidates = shelters.filter((s) => !s.state.collapsed);
936:     if (!candidates.length) {
937:       toast('NO SHELTER LEFT', `${c.name} has nowhere to go.`, 'alert');
938:       return;
939:     }
940:     candidates.sort((a, b) => dist(c.x, c.y, a.x, a.y) - dist(c.x, c.y, b.x, b.y));
941:     const dest = candidates[0];
942:     c.state = 'travel';
943:     c.targetShelterId = dest.id;
944:     c.shelterId = null;
945:     c.hp = Math.max(1, c.hp);
946:     game.team = game.team.filter((id) => id !== c.id);
947:     toast('SENT AHEAD', `${c.name} will hold ${dest.name} until you call.`, '');
948:     Sound.ui();
