175:   const MUTE_KEY = 'nightfall.mute.v1';
176:   function loadBest() {
177:     try { return parseInt(localStorage.getItem(BEST_KEY) || '0', 10) || 0; } catch (e) { return 0; }
178:   }
179:   function saveBest(n) {
180:     try { localStorage.setItem(BEST_KEY, String(n)); } catch (e) { /* private mode */ }
181:   }
182:   function loadMuted() {
183:     try { return localStorage.getItem(MUTE_KEY) === '1'; } catch (e) { return false; }
184:   }
185:   function saveMuted(v) {
186:     try { localStorage.setItem(MUTE_KEY, v ? '1' : '0'); } catch (e) { /* ignore */ }
